package org.marketreview.nativeapp;
import org.json.*;
import java.io.*;
import java.nio.channels.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
public final class KnowledgeAiHost {
 private KnowledgeAiHost(){}
 static final int DRAFT_LIMIT=2*1024*1024;
 static void need(boolean b,String s)throws Exception{if(!b)throw new Exception(s);}
 static byte[] bytes(JSONObject o){return o.toString().getBytes(StandardCharsets.UTF_8);}
 static boolean equal(Object a,Object b)throws Exception{return AiSettingsModel.equal(a,b);}
 public static String identity(JSONObject d)throws Exception{String kind=d.optString("kind"),id=d.optString("id");need((kind.equals("docs")||kind.equals("collections"))&&d.opt("id") instanceof String&&!id.isEmpty()&&id.length()<=200,"需要精确的来源类型与ID");return kind+":"+id;}
 public static JSONObject reference(JSONObject d)throws Exception{identity(d);JSONObject row=d.optJSONObject("row");need(row!=null&&Objects.equals(row.opt("id"),d.opt("id"))&&row.opt("text") instanceof String&&(!row.has("originalText")||row.opt("originalText") instanceof String),"来源身份或完整正文无效");return new JSONObject().put("kind",d.get("kind")).put("id",d.get("id")).put("bodySha256",AiSettingsModel.hash((row.getString("text")+'\0'+row.optString("originalText")).getBytes(StandardCharsets.UTF_8))).put("rowSha256",ResearchRuns.fingerprint(row)).put("textBytes",row.getString("text").getBytes(StandardCharsets.UTF_8).length).put("originalTextBytes",row.optString("originalText").getBytes(StandardCharsets.UTF_8).length);}
 public static JSONArray catalogue(JSONArray input)throws Exception{need(input.length()<=10000&&input.toString().getBytes(StandardCharsets.UTF_8).length<=32*1024*1024,"本机资料目录过大，未截断");Set<String> ids=new HashSet<>();JSONArray refs=new JSONArray();for(int i=0;i<input.length();i++){JSONObject d=input.getJSONObject(i);need(ids.add(identity(d)),"同来源类型的ID重复，不能选择");refs.put(reference(d));}return refs;}
 public static JSONObject selection(JSONArray input)throws Exception{need(input.length()<=20&&input.toString().getBytes(StandardCharsets.UTF_8).length<=512*1024,"选择超过20项或512KiB，未截断");JSONArray refs=catalogue(input);for(int i=0;i<input.length();i++)need(!input.getJSONObject(i).getJSONObject("row").getString("text").trim().isEmpty(),"所选材料没有完整可用本机正文");return new JSONObject().put("materials",new JSONArray(input.toString())).put("manifest",refs).put("count",input.length());}
 public static JSONObject confirm(JSONObject held,JSONArray current)throws Exception{need(equal(selection(held.getJSONArray("materials")),held)&&held.getJSONArray("materials").length()>0,"先明确选择完整资料");catalogue(current);Map<String,JSONObject> map=new HashMap<>();for(int i=0;i<current.length();i++)map.put(identity(current.getJSONObject(i)),current.getJSONObject(i));JSONArray refs=held.getJSONArray("manifest");for(int i=0;i<refs.length();i++){JSONObject ref=refs.getJSONObject(i);String key=identity(ref);need(map.containsKey(key)&&equal(reference(map.get(key)),ref),"来源已变化或缺失；原冻结材料保留，请重新选择");}return new JSONObject(held.toString());}
 public static JSONObject draft(String question,JSONObject selected,JSONObject preferences,String search,int view,String archive)throws Exception{need(question.getBytes(StandardCharsets.UTF_8).length<=8000&&search.getBytes(StandardCharsets.UTF_8).length<=2000&&view>=0&&view<=2,"草稿问题或阅读位置超过边界");need(archive.isEmpty()||archive.matches("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}\\.json"),"档案必须为私有目录内的精确文件名");need(equal(selection(selected.getJSONArray("materials")),selected),"选择清单与完整材料不一致");JSONObject out=new JSONObject().put("schema","native-knowledge-ai-host-draft/v1").put("question",question).put("selection",new JSONObject(selected.toString())).put("preferences",AiSettingsModel.preferences(preferences)).put("search",search).put("view",view).put("archive",archive);need(bytes(out).length<=DRAFT_LIMIT,"完整草稿过大，未截断");return out;}
 public static JSONObject validate(JSONObject state)throws Exception{JSONObject expected=draft(state.getString("question"),state.getJSONObject("selection"),state.getJSONObject("preferences"),state.getString("search"),state.getInt("view"),state.getString("archive"));need(equal(expected,state),"草稿字段、来源摘要或模式无效");return expected;}
 static JSONObject storedObject(byte[] raw)throws Exception{
  String text=new String(raw,StandardCharsets.UTF_8);need(Arrays.equals(raw,text.getBytes(StandardCharsets.UTF_8))&&text.indexOf('\0')<0,"stored-json-encoding-invalid");
  JSONTokener tokener=new JSONTokener(text);Object value=tokener.nextValue();need(value instanceof JSONObject&&tokener.nextClean()==0,"stored-json-trailing-or-invalid");return (JSONObject)value;
 }
 public static final class Store {
  private final File directory,file;
  public Store(File privateDirectory){directory=privateDirectory;file=new File(directory,"draft.json");}
  private byte[] readBytes()throws Exception{need(file.isFile()&&file.length()>0&&file.length()<=DRAFT_LIMIT,"私有完整草稿不可读或过大");byte[] b;try(InputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] block=new byte[16384];int n;while((n=in.read(block))!=-1){need(out.size()+n<=DRAFT_LIMIT,"私有完整草稿过大");out.write(block,0,n);}b=out.toByteArray();}validate(storedObject(b));return b;}
  public JSONObject marker()throws Exception{if(!file.exists())return new JSONObject();return new JSONObject().put("schema","knowledge-ai-host-marker/v1").put("sha256",AiSettingsModel.hash(readBytes()));}
  public JSONObject read(JSONObject marker)throws Exception{need(marker.length()==2&&"knowledge-ai-host-marker/v1".equals(marker.opt("schema"))&&marker.optString("sha256").matches("[a-f0-9]{64}"),"短状态标识无效");byte[] b=readBytes();need(AiSettingsModel.hash(b).equals(marker.opt("sha256")),"草稿摘要已变化；未恢复替代版本");return storedObject(b);}
  public synchronized JSONObject save(JSONObject state,JSONObject expected)throws Exception{JSONObject checked=validate(state);need(directory.isDirectory()||directory.mkdirs(),"私有目录不可用");try(RandomAccessFile lockFile=new RandomAccessFile(new File(directory,"draft.lock"),"rw");FileChannel channel=lockFile.getChannel();FileLock lock=channel.tryLock()){need(lock!=null,"草稿正被另一个页面写入");need(equal(marker(),expected),"草稿版本已变化，未覆盖其他修改");byte[] b=bytes(checked);Path temp=Files.createTempFile(directory.toPath(),"draft-",".tmp");try{Files.write(temp,b);try(FileOutputStream sync=new FileOutputStream(temp.toFile(),true)){sync.getFD().sync();}Files.move(temp,file.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(temp);}JSONObject result=new JSONObject().put("schema","knowledge-ai-host-marker/v1").put("sha256",AiSettingsModel.hash(b));need(equal(read(result),checked),"草稿写后核对失败");return result;}}
 }
}
